// Evenly spaced dots on land for the hero globe. Generated from Natural Earth 110m
// (public domain) via world-atlas (ISC). 2388 points as [lat*10, lon*10] int16 pairs.
// Do not edit by hand.

const B64 = ''

export function landDots(): Float32Array {
    const bin = atob(B64)
    const buf = new ArrayBuffer(bin.length)
    const view = new Uint8Array(buf)
    for (let i = 0; i < bin.length; i++) view[i] = bin.charCodeAt(i)
    const ints = new Int16Array(buf)
    const out = new Float32Array(ints.length)
    for (let i = 0; i < ints.length; i++) out[i] = ints[i] / 10
    return out
}
